//! Helpers shared by the Rust backends ([`crate::abi`], [`crate::syscalls`], [`crate::exec`]).

use std::collections::HashMap;
use std::fmt::Write as _;

use anyhow::{Result, bail};

use crate::ir::{Prim, TyRef, names};

/// First line of every generated file; `source` is the WIT path the file was generated from.
pub fn header(source: &str) -> String {
    format!("// @generated by wasixv2-codegen from `{source}`. DO NOT EDIT.\n")
}

/// Extracts the WIT source path from a generated file's [`header`].
pub fn source_from_header(generated: &str) -> Option<&str> {
    let line = generated.lines().next()?;
    let rest = line.strip_prefix("// @generated by wasixv2-codegen from `")?;
    rest.strip_suffix("`. DO NOT EDIT.")
}

const RUST_KEYWORDS: &[&str] = &[
    "abstract", "as", "async", "await", "become", "box", "break", "const", "continue", "do", "dyn",
    "else", "enum", "extern", "false", "final", "fn", "for", "gen", "if", "impl", "in", "let",
    "loop", "macro", "match", "mod", "move", "mut", "override", "priv", "pub", "ref", "return",
    "static", "struct", "trait", "true", "try", "type", "typeof", "unsafe", "unsized", "use",
    "virtual", "where", "while", "yield",
];

/// Identifiers that cannot be written as raw identifiers.
const UNRAWABLE: &[&str] = &["_", "self", "Self", "crate", "super"];

/// One Rust namespace; rejects names that collide after case conversion.
pub struct Namespace {
    what: &'static str,
    reserved: &'static [&'static str],
    seen: HashMap<String, String>,
}

impl Namespace {
    pub fn new(what: &'static str, reserved: &'static [&'static str]) -> Self {
        Self {
            what,
            reserved,
            seen: HashMap::new(),
        }
    }

    pub fn claim(&mut self, ident: String, origin: String) -> Result<()> {
        let what = self.what;
        if UNRAWABLE.contains(&ident.as_str()) {
            bail!("{origin} maps to Rust {what} `{ident}`, which is not a usable identifier");
        }
        if self.reserved.contains(&ident.as_str()) {
            bail!("{origin} maps to Rust {what} `{ident}`, which is reserved by generated code");
        }
        if let Some(prev) = self.seen.get(&ident) {
            bail!("{origin} and {prev} both map to Rust {what} `{ident}`");
        }
        self.seen.insert(ident, origin);
        Ok(())
    }
}

/// Escapes keywords; callers reject identifiers that cannot be escaped (see [`Namespace`]).
pub(crate) fn raw(name: &str) -> String {
    if RUST_KEYWORDS.contains(&name) {
        format!("r#{name}")
    } else {
        name.to_string()
    }
}

pub(crate) fn ident(kebab: &str) -> String {
    raw(&names::snake(kebab))
}

pub(crate) fn type_name(kebab: &str) -> String {
    names::upper_camel(kebab)
}

pub(crate) fn prim(p: Prim) -> &'static str {
    match p {
        Prim::U8 => "u8",
        Prim::U16 => "u16",
        Prim::U32 => "u32",
        Prim::U64 => "u64",
        Prim::S8 => "i8",
        Prim::S16 => "i16",
        Prim::S32 => "i32",
        Prim::S64 => "i64",
    }
}

pub(crate) fn ty(t: &TyRef) -> String {
    match t {
        TyRef::Prim(p) => prim(*p).to_string(),
        TyRef::Named(n) => type_name(n),
        TyRef::Array(elem, n) => format!("[{}; {n}]", ty(elem)),
    }
}

pub(crate) fn wit_ty(t: &TyRef) -> String {
    match t {
        TyRef::Prim(p) => p.wit_name().to_string(),
        TyRef::Named(n) => n.clone(),
        TyRef::Array(elem, n) => format!("list<{}, {n}>", wit_ty(elem)),
    }
}

/// `expr as to` unless `from` already is `to`.
pub(crate) fn cast(expr: &str, from: Prim, to: Prim) -> String {
    if from == to {
        expr.to_string()
    } else {
        format!("{expr} as {}", prim(to))
    }
}

/// Appends `docs` as `///` lines.
pub(crate) fn push_docs(out: &mut String, docs: &[String]) {
    for d in docs {
        if d.trim().is_empty() {
            out.push_str("///\n");
        } else {
            let _ = writeln!(out, "/// {}", d.trim_start());
        }
    }
}
